"""Dependency-free, accessible interface for the measured public release."""
HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compute Forecast · Research Observatory</title><style>
:root{--paper:#f4f2eb;--white:#fffefa;--ink:#162730;--muted:#62717a;--line:#d9ddd7;--blue:#3158df;--light:#e7edff;--amber:#aa601b;--green:#187666}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,select{font:inherit}button,a,select{touch-action:manipulation}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #d98b2b;outline-offset:3px}a{color:var(--blue);text-underline-offset:3px}button{cursor:pointer}header{background:var(--ink);color:#edf2ed;padding:22px 4vw;display:flex;align-items:center;justify-content:space-between;gap:20px}header a{color:#d8e1ef;text-decoration:none;font-size:13px}.brand{font-size:19px;font-weight:650;letter-spacing:-.6px}.brand b{font-weight:400;color:#a7b6bc}.brand small{display:block;font:10px/1.6 ui-monospace,monospace;letter-spacing:2px;color:#a7b6bc}.signal{display:inline-block;width:7px;height:7px;background:#75d3b5;border-radius:50%;margin-right:9px}nav{display:flex;gap:8px;padding:13px 4vw;border-bottom:1px solid var(--line);overflow:auto;background:var(--white);position:sticky;top:0;z-index:2}nav button{border:0;background:transparent;border-radius:6px;padding:9px 14px;white-space:nowrap;color:var(--muted)}nav button[aria-current=true]{color:var(--blue);background:var(--light);font-weight:600}main{max-width:1430px;padding:34px 4vw 65px;margin:auto}.eyebrow{font:11px/1.5 ui-monospace,monospace;letter-spacing:1.7px;color:var(--muted);text-transform:uppercase}h1{font-size:clamp(34px,4.5vw,61px);font-weight:520;letter-spacing:-2.8px;line-height:1.06;max-width:790px;margin:14px 0 18px}h2{font-size:24px;letter-spacing:-.6px;font-weight:550;margin:0 0 9px}h3{font-size:16px;margin:0 0 8px;font-weight:600}p{margin:0 0 15px}.lede{color:var(--muted);font-size:17px;max-width:700px}.hero{display:grid;grid-template-columns:1.65fr 1fr;gap:40px;align-items:center;margin-bottom:30px}.instrument{min-height:245px;background:var(--ink);border-radius:12px;position:relative;overflow:hidden;color:white;padding:26px;box-shadow:0 17px 35px #16273015}.instrument:before{content:"";position:absolute;inset:-50%;background:repeating-linear-gradient(72deg,transparent 0 39px,#7a98bd18 40px 41px);transform:rotate(10deg)}.instrument svg{width:100%;height:135px;position:relative}.instrument .eyebrow{color:#a9bbc5}.instrument strong{position:relative;font-size:17px;font-weight:500}.chip{display:inline-block;border:1px solid var(--line);border-radius:99px;padding:4px 9px;font-size:11px;color:var(--muted);background:var(--white);margin:0 6px 6px 0}.chip.good{color:var(--green);background:#eaf5ef;border-color:#c5ded4}.chip.warn{color:var(--amber);background:#fff3dc;border-color:#e6d5b8}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:24px 0}.card{padding:23px;background:var(--white);border:1px solid var(--line);border-radius:9px;min-width:0}.metric{font-size:34px;letter-spacing:-1px;margin:5px 0}.sub{font-size:12px;color:var(--muted)}.two{display:grid;grid-template-columns:1.35fr 1fr;gap:20px;margin:22px 0}.callout{padding:19px 22px;background:#e9edfa;border-left:3px solid var(--blue);border-radius:0 7px 7px 0;margin:20px 0}.callout.amber{background:#fbefdf;border-color:#ba7a2b}.chart{width:100%;display:block;overflow:visible}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px;font-variant-numeric:tabular-nums}th{text-align:left;font-weight:500;font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:var(--muted);padding:12px 10px;border-bottom:1px solid var(--line)}td{padding:12px 10px;border-bottom:1px solid #e9ece6}td.num,th.num{text-align:right}tr.selected{background:#edf1ff}.legend{display:flex;gap:15px;flex-wrap:wrap;color:var(--muted);font-size:12px}.legend i{width:8px;height:8px;display:inline-block;margin-right:5px;border-radius:50%}.controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:18px 0}select,.action{border:1px solid var(--line);border-radius:6px;background:var(--white);padding:9px 12px;color:var(--ink)}.action.primary{background:var(--blue);color:white;border-color:var(--blue)}.action:disabled{opacity:.4;cursor:default}.sectiontop{display:flex;justify-content:space-between;gap:20px;align-items:start;margin:8px 0 24px}.sectiontop p{color:var(--muted);max-width:670px}.statline{display:flex;gap:20px;flex-wrap:wrap}.statline strong{display:block;color:var(--ink);font-size:22px;font-weight:500}.flow{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:20px 0}.flow>div{padding:16px;background:#f0f2ec;border-radius:6px;font-size:12px;color:var(--muted)}.flow strong{display:block;color:var(--ink);font-size:24px}.heat{width:100%;border-spacing:3px;border-collapse:separate}.heat td{border:0;padding:7px;font:11px ui-monospace,monospace;text-align:center;border-radius:3px}.heat td:first-child{text-align:left;white-space:nowrap;background:transparent}.heat button{width:100%;padding:2px;border:0;background:transparent;color:inherit}.mono{font:12px/1.65 ui-monospace,monospace;overflow-wrap:anywhere}.tracegrid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.tracecard{border:1px solid var(--line);background:var(--white);border-radius:9px;overflow:hidden}.tracehead{padding:18px 22px;background:#eef1e9;border-bottom:1px solid var(--line)}.tracehead.trained{background:#e8edff}.tracebody{padding:22px}.trial{display:flex;gap:12px;margin:0 0 13px;align-items:start}.trial .n{flex:0 0 26px;height:26px;background:#edf0e9;border-radius:50%;text-align:center;line-height:26px;font-size:12px}.trial span{display:block;font-size:12px;color:var(--muted)}.timeline{border-left:1px solid #b8c6ce;padding-left:25px;margin:25px 0 25px 8px}.event{position:relative;margin-bottom:25px}.event:before{content:"";position:absolute;left:-31px;top:5px;width:10px;height:10px;border-radius:50%;background:var(--blue);border:2px solid var(--paper)}.event.read:before{background:#98aaa9}.event.write:before{background:var(--green)}.event .card{margin-top:8px;padding:16px}.source{padding:15px 0;border-bottom:1px solid var(--line)}.empty{padding:30px;color:var(--muted);border:1px dashed var(--line);border-radius:8px}.download{display:inline-block;padding:10px 15px;border:1px solid var(--blue);border-radius:6px;margin:8px 8px 8px 0;text-decoration:none}.fine{font-size:12px;color:var(--muted);margin-top:15px}footer{border-top:1px solid var(--line);padding:20px 4vw;font-size:11px;color:var(--muted);display:flex;justify-content:space-between;gap:20px}#error{color:#8c2e27;padding:30px;max-width:800px;margin:auto}details{margin:12px 0}summary{cursor:pointer;font-size:13px}.scope{font-size:12px;padding:11px 14px;border:1px solid var(--line);border-radius:5px;margin-top:16px;color:var(--muted)}@media(max-width:900px){.hero,.two{grid-template-columns:1fr}.instrument{display:none}.grid{grid-template-columns:repeat(2,1fr)}.flow{grid-template-columns:repeat(3,1fr)}.tracegrid{grid-template-columns:1fr}h1{letter-spacing:-1.5px}.card{padding:18px}}@media(max-width:520px){main{padding:25px 5vw}.grid{gap:8px}.metric{font-size:27px}nav{padding-left:3vw}nav button{padding:9px}header{padding:17px 5vw}.brand b{display:none}.flow{grid-template-columns:1fr 1fr}footer{display:block}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style></head><body><header><div class="brand">↗ Compute Forecast <b>/ observatory</b><small>RESEARCH THAT LEAVES A PAPER TRAIL</small></div><a href="https://github.com/howdymary/compute-forecasting/tree/compute-observatory" target="_blank" rel="noopener">Source & artifacts ↗</a></header><nav aria-label="Research views"><button data-view="overview" aria-current="true">01 Overview</button><button data-view="benchmarks">02 Benchmarks</button><button data-view="replay">03 Policy replay</button><button data-view="evidence">04 Evidence & memory</button><button data-view="reproduce">05 Reproduce</button></nav><main id="app" aria-live="polite"><div class="empty">Loading measured artifacts…</div></main><div id="error" hidden></div><footer><span>Pacific Machines (2026) · gpu-price-pack v0.1.1-handover · raw data kept private</span><span id="revision"></span></footer><script>
'use strict';let D,view='overview',frameDate='',replayDate='',step=0,playing=false,timer=null,forecastRows=[];
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(n,d=6)=>n==null?'—':Number(n).toFixed(d),pct=n=>n==null?'undefined':(n*100).toFixed(2)+'%',name=s=>({'starting_policy':'Starting policy','frozen_trained_policy':'Frozen SFT · epoch 1','fixed_search':'Fixed search','last_value':'Last value','last_value_empirical':'Empirical intervals','drift':'Drift','seasonal_naive':'Seasonal naive'}[s]||s.replaceAll('_',' ')),link=(url,label)=>'<a target="_blank" rel="noopener" href="'+esc(url)+'">'+esc(label)+' ↗</a>',chip=(s,c='')=>'<span class="chip '+c+'">'+esc(s)+'</span>';
function comparison(rows,selected){return '<div class="tablewrap"><table><thead><tr><th>Policy / search</th><th class="num">Pinball ↓</th><th class="num">Skill vs last value</th></tr></thead><tbody>'+rows.map(r=>'<tr class="'+(r.policy===selected?'selected':'')+'"><td>'+esc(name(r.policy))+'</td><td class="num">'+fmt(r.pooled_pinball)+'</td><td class="num">'+(r.skill_vs_last_value==null?'—':pct(r.skill_vs_last_value))+'</td></tr>').join('')+'</tbody></table></div>'}
function trainingChart(){let rows=D.development.comparisons.filter(r=>r.policy==='starting_policy'||r.policy.startsWith('sft_epoch_')),values=rows.map(r=>r.pooled_pinball),lo=Math.min(...values)*.995,hi=Math.max(...values)*1.005,w=620,h=200,x=i=>60+i*(w-100)/(rows.length-1),y=v=>25+(hi-v)/(hi-lo)*135;return '<svg class="chart" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Development pinball across starting model and five saved SFT checkpoints">'+[lo,(hi+lo)/2,hi].map(v=>'<line x1="58" y1="'+y(v)+'" x2="600" y2="'+y(v)+'" stroke="#dce1db"/><text x="0" y="'+(y(v)+4)+'" fill="#62717a" font-size="10">'+fmt(v,5)+'</text>').join('')+'<polyline points="'+values.map((v,i)=>x(i)+','+y(v)).join(' ')+'" fill="none" stroke="#3158df" stroke-width="2.5"/>'+rows.map((r,i)=>'<circle cx="'+x(i)+'" cy="'+y(r.pooled_pinball)+'" r="4" fill="#3158df"/><text x="'+x(i)+'" y="185" text-anchor="middle" fill="#62717a" font-size="10">'+(i===0?'Start':'SFT '+i)+'</text>').join('')+'</svg>'}
function overview(){let f=D.final,s=f.comparisons.find(r=>r.policy==='starting_policy'),t=f.comparisons.find(r=>r.policy==='frozen_trained_policy'),delta=t.pooled_pinball/s.pooled_pinball-1,b=f.paired_block_bootstrap,better=delta<0;return '<section class="hero"><div><div class="eyebrow"><span class="signal"></span>PACIFIC / TRACK 2 · MEASURED RELEASE</div><h1>A market forecast<br>you can audit.</h1><p class="lede">Can a trained research policy choose better forecasting experiments? We tested it on advertised GPU rental rates, and kept every result.</p>'+chip('50 real Tinker updates','good')+chip('Frozen evaluation','good')+chip('6 trials per policy')+'</div><div class="instrument"><div class="eyebrow">OBSERVATORY / 001</div><svg viewBox="0 0 350 130" aria-hidden="true"><g fill="none" stroke="#a5b7d0" opacity=".55"><ellipse cx="175" cy="65" rx="135" ry="40"/><ellipse cx="175" cy="65" rx="40" ry="60" transform="rotate(60 175 65)"/><ellipse cx="175" cy="65" rx="40" ry="60" transform="rotate(-60 175 65)"/></g><circle cx="175" cy="65" r="22" fill="#5077f5"/><circle cx="310" cy="65" r="5" fill="#8be0be"/><circle cx="106" cy="33" r="4" fill="#f0bf76"/></svg><strong>Hypothesis → experiment → criticism</strong><div class="sub" style="color:#a9bbc5">Actual traces. Fixed budgets. Visible uncertainty.</div></div></section><div class="grid">'+[['FINAL SFT PINBALL',fmt(t.pooled_pinball),'Five rolling evaluation origins'],['VS STARTING POLICY',(Math.abs(delta)*100).toFixed(2)+'% '+(better?'lower':'higher'),'Same information and six-trial budget'],['GENUINE TRAINING','50 updates','Qwen3.5-4B · LoRA · supervised fine-tuning'],['TEMPORAL SAMPLE','5 / 6 / 5','Training / development / final origins']].map(a=>'<div class="card"><div class="eyebrow">'+a[0]+'</div><div class="metric">'+a[1]+'</div><div class="sub">'+a[2]+'</div></div>').join('')+'</div><div class="callout '+(better?'':'amber')+'"><h3>'+ (better?'A measured final difference, with substantial uncertainty.':'Training did not establish a forecasting advantage.')+'</h3><p>The frozen SFT policy has '+(Math.abs(delta)*100).toFixed(2)+'% '+(better?'lower':'higher')+' pooled pinball loss than the starting model on this final sample. The development study favored the starting model. Five dependent origins cannot establish a general research capability.</p><div class="sub">Exploratory mean-origin difference interval: ['+fmt(b.lower_percentile_2_5)+', '+fmt(b.upper_percentile_97_5)+']. Moving blocks of 2; 2,000 resamples. Negative differences favor SFT.</div></div><div class="two"><section class="card"><h2>Frozen final comparison</h2><p class="sub">Exact official scorer losses · lower is better. All policies receive two common trials and four further experiments.</p>'+comparison(f.comparisons,'frozen_trained_policy')+'<p class="fine">Random seeds are sensitivity checks, not independent replications. '+link(D.links.final,'Inspect actual final run')+'</p></section><section class="card"><h2>Learning, without a victory lap.</h2><p class="sub">Development performance across five actual saved checkpoints. The first SFT checkpoint was selected before final evaluation.</p>'+trainingChart()+'<div class="sub">Vertical axis is expanded and labeled to expose small differences.</div><div class="scope">SFT learns bounded experiment choices from completed training experiments. This project does not claim reinforcement learning, full-weight training, or improved general research ability.</div><p class="fine">'+link(D.links.training,'Training and checkpoints')+'</p></section></div><section class="card"><h2>Millions of offers. A small forecasting experiment.</h2><div class="flow">'+[['3.78M','advertised offer rows'],['26','candidate weekly origins'],[D.representation.eligible_origins,'eligible representation origins'],['5 + 6','policy train / development dates'],['5','frozen rolling final dates']].map(a=>'<div><strong>'+a[0]+'</strong>'+a[1]+'</div>').join('')+'</div><p class="sub">Rows are not independent forecast cases. The representation and policy study covers the eligible afhubbard headline daily-statistics subset; the official November 6 export covers the complete headline catalog.</p></section><div class="two"><section class="card"><h2>November 6 forecast export</h2><p>'+esc(D.submission.forecast_rows)+' rows · '+esc(D.submission.n_headline_series)+' headline series · 1, 3 and 7 days.</p><p class="sub">The full-catalog method was chosen on development scores: '+esc(name(D.submission.method))+'. Future competition truth was not loaded or scored.</p><a class="download" href="/files/forecasts.csv">Download official CSV ↓</a><a class="download" href="/files/outlook.md">2–3 year scenarios ↓</a></section><section class="card"><h2>The research loop has receipts.</h2><p>Evidence researcher, forecast scientist and skeptic use Exa and shared past.dev records to choose and critique actual completed experiments.</p><div class="statline"><div><strong>'+D.memory.writers.length+'</strong>agent writers</div><div><strong>'+D.memory.readers.length+'</strong>agent readers</div><div><strong>✓</strong>cross-agent use verified</div></div><p class="fine">Current methodology research stays outside historical forecast inputs.</p></section></div>'}
function benchmarks(){let frames=D.representation.frames.filter(f=>f.status==='completed');if(!frameDate)frameDate=frames.at(-1).origin;let f=frames.find(f=>f.origin===frameDate),rows=f.methods.slice().sort((a,b)=>a.pinball-b.pinball),max=Math.max(...rows.map(r=>r.pinball)),metadata=f.series.map(s=>s.gpu_model+' / '+s.pricing_tier+' / '+s.statistic);return '<div class="sectiontop"><div><div class="eyebrow">THE NUMERICAL BENCHMARK</div><h2>Representation is an experiment.</h2><p>24 Ridge configurations: level or log targets; target-only, raw-composition or fixed-basket features; 28 or 56 days; two regularization values. Official targets remain unchanged.</p></div>'+chip('No random row split','good')+'</div><div class="controls"><label for="origin">Development origin</label><select id="origin">'+frames.map(r=>'<option '+(r.origin===f.origin?'selected':'')+'>'+r.origin+'</option>').join('')+'</select><span class="sub">'+f.series.length+' eligible series · labels through '+esc(f.label_end)+'</span></div><div class="scope">Observed scope on this date: '+esc(metadata.join('; '))+'. Early dates with no eligible target are excluded, not replaced with synthetic observations.</div><div class="two"><section class="card"><h2>All configurations, including failures</h2><div class="tablewrap"><table><thead><tr><th>Configuration</th><th class="num">Pinball ↓</th><th class="num">Skill</th></tr></thead><tbody>'+rows.map(r=>'<tr class="'+(!r.config_id.startsWith('ridge_')?'selected':'')+'"><td>'+esc(r.config_id)+'</td><td class="num">'+fmt(r.pinball)+'</td><td class="num">'+pct(r.skill_pooled)+'</td></tr>').join('')+'</tbody></table></div></section><section><div class="card"><h2>Forecast horizons</h2><p class="sub">Select a method to inspect its exact per-horizon official loss.</p><select id="method" aria-label="Forecast configuration">'+rows.map(r=>'<option value="'+esc(r.config_id)+'">'+esc(r.config_id)+'</option>').join('')+'</select><div id="horizons"></div></div><div class="card" style="margin-top:18px"><h2>Coverage and caveats</h2><p>Only '+D.representation.eligible_origins+' of 26 attempted development origins were eligible. Matured chronological labels are required for every experiment.</p><p class="sub">The pack is a retrospective frozen vintage. A row date cannot prove that the exact value was available in real time. Missing raw composition data is explicit; the configuration identity proxy is imperfect.</p>'+link(D.links.grid,'Full grid and provenance')+'</div></section></div><section class="card"><h2>Full-catalog baseline selection</h2><p class="sub">This is a separate six-origin development comparison for the complete official submission, not the narrow policy subset.</p><table><thead><tr><th>Official method</th><th class="num">Pooled pinball ↓</th></tr></thead><tbody>'+D.official_baseline.methods.map(r=>'<tr class="'+(r.method===D.official_baseline.selected_method?'selected':'')+'"><td>'+esc(name(r.method))+'</td><td class="num">'+fmt(r.pooled_pinball)+'</td></tr>').join('')+'</tbody></table></section>'}
function horizons(){let f=D.representation.frames.find(f=>f.origin===frameDate),r=f.methods.find(m=>m.config_id===$('#method').value);$('#horizons').innerHTML='<table><thead><tr><th>Horizon</th><th class="num">Pinball ↓</th><th class="num">Cells</th></tr></thead><tbody>'+Object.entries(r.by_horizon).map(([h,v])=>'<tr><td>'+esc(h)+' days</td><td class="num">'+fmt(v.pinball)+'</td><td class="num">'+esc(v.n_cells)+'</td></tr>').join('')+'</tbody></table>'}
function replayCard(which,title){let r=D.traces[which].traces.find(r=>r.origin===replayDate),visible=r.revealed_configs.slice(0,step+2),decisions=r.decisions.slice(0,step);return '<section class="tracecard"><div class="tracehead '+(which==='trained'?'trained':'')+'"><h3>'+title+'</h3><span class="sub">'+(which==='trained'?'Actual saved epoch 1 checkpoint':'Unmodified starting model')+'</span></div><div class="tracebody">'+visible.map((c,i)=>'<div class="trial"><div class="n">'+(i+1)+'</div><div class="mono">'+esc(c)+'<span>'+(i<2?'Common initial experiment':esc(name(decisions[i-2].selected_family_id))+' · measured validation '+fmt(decisions[i-2].revealed_validation_result.loss))+'</span></div></div>').join('')+(step===4?'<div class="callout"><div class="eyebrow">FINAL CHOICE</div><h3 class="mono">'+esc(r.selected_config_id)+'</h3><p>Held-out pinball: <strong>'+fmt(r.future_pinball)+'</strong> · '+r.future_cells+' scored cells.</p></div>':'<p class="fine">Held-out outcome remains hidden until search finishes.</p>')+'</div></section>'}
function replay(){if(!replayDate)replayDate=D.final.final_origins[0];return '<div class="sectiontop"><div><div class="eyebrow">SAME SCENARIO / SAME BUDGET</div><h2>Watch the policy choose.</h2><p>Replay actual recorded decisions from the frozen evaluation. Each policy sees the same matured validation folds, then chooses four experiments after two common trials.</p></div>'+chip('Recorded actual traces','warn')+'</div><div class="controls"><label for="replay-origin">Final origin</label><select id="replay-origin">'+D.final.final_origins.map(d=>'<option '+(d===replayDate?'selected':'')+'>'+d+'</option>').join('')+'</select><button class="action primary" id="play">'+(playing?'Pause':'Play recorded trace')+'</button><button class="action" id="next" '+(step===4?'disabled':'')+'>Next experiment →</button><button class="action" id="reset">Reset</button><span class="sub">'+(step+2)+' / 6 trials revealed</span></div><div class="tracegrid">'+replayCard('starting','Starting policy')+replayCard('trained','Frozen SFT policy')+'</div><div class="scope">Animations reveal saved actions and measured outcomes; they do not call live inference. Later rolling evaluation dates can use matured earlier outcomes. Model weights and the selection protocol remain frozen. No web news or cross-agent memory enters these observations.</div>'}
function evidence(){return '<div class="sectiontop"><div><div class="eyebrow">HYPOTHESIS → EVIDENCE → EXPERIMENT → CRITICISM</div><h2>Research, with named authors.</h2><p>Three roles share real past.dev records. Every required recall was returned, and subsequent decisions carry the record IDs they used.</p></div>'+chip('Current methods research','warn')+'</div><div class="grid">'+[['WRITERS',D.memory.writers.length],['READERS',D.memory.readers.length],['CROSS-AGENT USE','Verified'],['MEMORY GAIN','Not claimed']].map(a=>'<div class="card"><div class="eyebrow">'+a[0]+'</div><div class="metric">'+a[1]+'</div></div>').join('')+'</div><div class="two"><section><h2>The actual exchange</h2><div class="timeline">'+D.memory.events.map(e=>'<article class="event '+e.event+'"><div class="eyebrow">'+esc(e.role)+' / '+esc(e.event)+'</div><div class="card"><h3>'+esc(e.selected_action||e.kind||'Read shared records')+'</h3>'+(e.summary&&Object.keys(e.summary).length?'<p>'+esc(e.summary.criticism||e.summary.hypothesis||e.summary.selected_action||e.summary.objection_id||'')+'</p>':'')+(e.experiment?'<p class="mono">'+esc(e.experiment.config_id)+'</p>'+chip('Hash-verified cached experiment')+'<p class="sub">Previously executed and officially scored. This loop reveals that result; it does not launch a new numerical run.</p>':'')+'<details><summary>Record provenance</summary><div class="mono">'+(e.source_id?'Written ID: '+esc(e.source_id)+'<br>':'')+(e.required_source_id?'Required: '+esc(e.required_source_id)+'<br>':'')+(e.returned_source_ids?'Returned: '+esc(e.returned_source_ids.join(', '))+'<br>':'')+(e.used_memory_source_ids?'Used: '+esc(e.used_memory_source_ids.join(', '))+'<br>':'')+esc(e.created_at)+'</div></details></div></article>').join('')+'</div></section><section><div class="card"><h2>Exa sources</h2><p class="sub">Retrieved during the event. Publication dates alone do not establish historical availability.</p>'+D.memory.sources.map(s=>'<div class="source">'+link(s.url,s.title||s.url)+'<div class="fine">Retrieved '+esc(s.retrieved_at||'during the run')+'</div></div>').join('')+'<p class="fine">'+link(D.links.memory,'Inspect actual execution and memory IDs')+'</p></div><div class="callout amber"><h3>Keep today out of yesterday.</h3><p>This current-methods loop is separate from the historical benchmark. Its sources and memory are never forecast features. No measured memory performance improvement is claimed.</p></div></section></div>'}
function reproduce(){return '<div class="sectiontop"><div><div class="eyebrow">REPRODUCIBILITY / PUBLIC RELEASE</div><h2>Follow the evidence all the way down.</h2><p>Source revisions, dataset hashes, saved configurations and failed experiments remain inspectable. All development and execution happened through GitHub and remote services.</p></div></div><div class="two"><section class="card"><h2>Release artifacts</h2><a class="download" href="/files/forecasts.csv">Official forecast CSV ↓</a><a class="download" href="/files/outlook.md">2–3 year scenario note ↓</a><a class="download" href="/files/outlook-scenarios.json">Scenario assumptions JSON ↓</a><a class="download" href="/api/release">Public measured results JSON ↓</a><a class="download" href="/files/demo.mp4">Two-minute submission video ↓</a><p class="fine">The long-term outlook is separate scenario analysis, with no fitted probabilities or observed resale-dollar anchor. It is not a calibrated confidence interval.</p><h3>One reproducible entrypoint</h3><p class="mono">compute-forecast reproduce --full-grid --train-policy</p><p class="sub">Run through the authorized compute-observatory GitHub Actions workflow. Requires account credentials and permitted dataset access; it does not run locally.</p><p>'+link(D.links.repository+'/blob/README.md','Setup and full protocol')+'</p></section><section class="card"><h2>Information boundaries</h2><p><strong>Primary instrument:</strong> advertised GPU rental offers. These are not executed transaction prices, guaranteed available capacity or physical GPU resale prices.</p><p><strong>Official cutoff:</strong> November 6, 2026, 23:59:59 UTC. The export does not load future competition outcomes.</p><p><strong>Final selection freeze:</strong> '+esc(D.freeze.frozen_at)+'. Five final origins: '+esc(D.final.final_origins.join(', '))+'.</p><p><strong>Licensing:</strong> compilation default is pending owner confirmation and upstream terms apply. Raw data is not redistributed. Pacific Machines attribution is retained.</p></section></div><div class="two"><section class="card"><h2>Execution receipts</h2>'+Object.entries(D.links).filter(([k])=>k!=='repository').map(([k,v])=>'<p>'+link(v,name(k))+'</p>').join('')+'<p class="sub">Training and final inference costs are unavailable, so no dollar estimate is invented. Runtime and per-call timing are retained in run artifacts.</p></section><section class="card"><h2>Precedents and limitations</h2><p>Provider and configuration normalization are established practices. We credit '+link('https://www.silicondata.com/products/silicon-index','Silicon Data')+' and '+link('https://semianalysis.com/gpu-pricing-index/','SemiAnalysis')+'.</p><p>Our contribution is a reproducible evaluation on the available pack. The effective temporal sample is small; frozen-vintage revision leakage and model pretraining knowledge cannot be fully excluded.</p><p class="sub">We do not claim the first GPU benchmark, a learned world model, reinforcement learning, or a forecasting breakthrough.</p></section></div><div class="scope mono">Dataset SHA-256: '+D.dataset_sha256+'<br>Public release source: '+D.code_sha+'<br>Forecast CSV SHA-256: '+esc(D.submission.forecast_csv_sha256)+'</div>'}
function render(){if(!D)return;clearTimeout(timer);playing=false;$('#app').innerHTML=({overview,benchmarks,replay,evidence,reproduce})[view]();document.querySelectorAll('nav button').forEach(b=>b.setAttribute('aria-current',String(b.dataset.view===view)));if(view==='benchmarks'){horizons();$('#origin').onchange=e=>{frameDate=e.target.value;render()};$('#method').onchange=horizons}if(view==='replay'){bindReplay()}}
function bindReplay(){$('#replay-origin').onchange=e=>{replayDate=e.target.value;step=0;render()};$('#reset').onclick=()=>{step=0;render()};$('#next').onclick=()=>{step=Math.min(4,step+1);render()};$('#play').onclick=()=>{if(playing){clearTimeout(timer);playing=false;$('#play').textContent='Play recorded trace';return}if(step===4)step=0;playing=true;tick()}}
function tick(){if(!playing)return;step=Math.min(4,step+1);$('#app').innerHTML=replay();bindReplay();if(step===4){playing=false;$('#play').textContent='Replay again';return}timer=setTimeout(tick,1800)}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;history.replaceState(null,'','#'+view);render();window.scrollTo(0,0)});async function start(){let r=await fetch('/api/release',{cache:'no-store'});if(!r.ok)throw Error('Measured release is not available yet ('+r.status+').');D=await r.json();if(D.schema_version!==1)throw Error('Unsupported measured artifact format');view=['overview','benchmarks','replay','evidence','reproduce'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';$('#revision').textContent='Revision '+D.code_sha.slice(0,7)+' · '+D.created_at.slice(0,10);render()}start().catch(e=>{$('#app').innerHTML='';$('#error').hidden=false;$('#error').textContent=e.message+' Please inspect the linked repository artifacts.'});
</script></body></html>'''
